'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/tooltip/md-gb-tooltip.js';
import {TooltipElement} from '@material/web/labs/gb/components/tooltip/tooltip-element.js';

/**
 * A Material Design plain or rich tooltip. Wraps <md-gb-tooltip>.
 * Docs: https://material-web.dev/3.0/components/tooltip/
 */
export const MdTooltip = createComponent({
  react: React,
  tagName: 'md-gb-tooltip',
  elementClass: TooltipElement,
  events: {
    onClose: 'close' as EventName<CustomEvent<{reason: string}>>,
    onClosed: 'closed' as EventName<CustomEvent<{reason: string}>>,
    onOpen: 'open' as EventName<Event>,
    onOpened: 'opened' as EventName<Event>,
  },
});

export type MdTooltipProps = React.ComponentProps<typeof MdTooltip>;
